//! JSON frames exchanged on `/ws`, tagged by `type`.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, sqlx::Type)]
#[serde(rename_all = "lowercase")]
#[sqlx(type_name = "message_kind", rename_all = "lowercase")]
pub enum MessageKind {
    Text,
    Image,
    Voice,
}

/// Frames sent by the app.
#[derive(Debug, Deserialize)]
#[serde(tag = "type")]
pub enum ClientEvent {
    /// `id` is generated by the app: resending after a reconnection is harmless.
    #[serde(rename = "message.send")]
    SendMessage {
        id: Uuid,
        kind: MessageKind,
        #[serde(default)]
        body: Option<String>,
        /// `<couple_id>/<file>` in the private `couple-media` bucket.
        #[serde(default)]
        media_path: Option<String>,
        #[serde(default)]
        duration_ms: Option<i32>,
    },
    /// Everything the partner sent up to `until` has been seen.
    #[serde(rename = "message.read")]
    MarkRead { until: DateTime<Utc> },
    #[serde(rename = "reaction.set")]
    SetReaction { message_id: Uuid, emoji: String },
    #[serde(rename = "reaction.clear")]
    ClearReaction { message_id: Uuid },
    #[serde(rename = "mood.set")]
    SetMood { energy: i16, mood: i16 },
    #[serde(rename = "typing")]
    Typing { active: bool },
    #[serde(rename = "ping")]
    Ping,
}

#[derive(Debug, Clone, Serialize, sqlx::FromRow)]
pub struct MessageRow {
    pub id: Uuid,
    pub couple_id: Uuid,
    pub sender_id: Option<Uuid>,
    pub kind: MessageKind,
    pub body: Option<String>,
    pub media_path: Option<String>,
    pub duration_ms: Option<i32>,
    pub created_at: DateTime<Utc>,
    pub read_at: Option<DateTime<Utc>>,
}

#[derive(Debug, Clone, Serialize, sqlx::FromRow)]
pub struct MoodRow {
    pub user_id: Uuid,
    pub energy: i16,
    pub mood: i16,
    pub updated_at: DateTime<Utc>,
}

/// Frames sent by the server.
#[derive(Debug, Serialize)]
#[serde(tag = "type")]
pub enum ServerEvent {
    #[serde(rename = "ready")]
    Ready {
        couple_id: Uuid,
        user_id: Uuid,
        partner_online: bool,
    },
    #[serde(rename = "presence")]
    Presence { user_id: Uuid, online: bool },
    #[serde(rename = "message.new")]
    Message { message: MessageRow },
    #[serde(rename = "message.read")]
    Read {
        reader_id: Uuid,
        until: DateTime<Utc>,
    },
    #[serde(rename = "reaction")]
    Reaction {
        message_id: Uuid,
        user_id: Uuid,
        /// `null` when the reaction was removed.
        emoji: Option<String>,
    },
    #[serde(rename = "mood")]
    Mood { mood: MoodRow },
    #[serde(rename = "typing")]
    Typing { user_id: Uuid, active: bool },
    /// Some events were missed (slow connection): reload from the database.
    #[serde(rename = "resync")]
    Resync,
    #[serde(rename = "pong")]
    Pong,
    #[serde(rename = "error")]
    Error { code: &'static str, message: String },
}

impl ServerEvent {
    pub fn error(code: &'static str, message: impl Into<String>) -> Self {
        Self::Error {
            code,
            message: message.into(),
        }
    }

    pub fn to_json(&self) -> String {
        serde_json::to_string(self).expect("server events always serialize")
    }
}
